var vue_default = "---\nlayout: article\ntitle: Start with Vue.js\ndescription: Build Vue.js apps with Appwrite and learn how to use our powerful backend to add authentication, user management, file storage, and more.\ndifficulty: beginner\nreadtime: 3\nback: /docs/quick-starts\n---\n\nLearn how to setup your first Vue project powered by Appwrite.\n{% section #step-1 step=1 title=\"Create project\" %}\nHead to the [Appwrite Console](https://cloud.appwrite.io/console).\n\n{% only_dark %}\n![Create project screen](/images/docs/quick-starts/dark/create-project.avif)\n{% /only_dark %}\n{% only_light %}\n![Create project screen](/images/docs/quick-starts/create-project.avif)\n{% /only_light %}\n\nIf this is your first time using Appwrite, create an account and create your first project.\n\nThen, under **Add a platform**, add a **Web app**. The **Hostname** should be `localhost`.\n\n{% partial file=\"note-on-cors.md\" /%}\n\n{% only_dark %}\n![Add a platform](/images/docs/quick-starts/dark/add-platform.avif)\n{% /only_dark %}\n{% only_light %}\n![Add a platform](/images/docs/quick-starts/add-platform.avif)\n{% /only_light %}\n\nYou can skip optional steps.\n\n{% /section %}\n{% section #step-2 step=2 title=\"Create Vue project\" %}\nCreate a Vue project.\n\n```sh\nnpm init vue@latest my-app && cd my-app\n```\n{% /section %}\n{% section #step-3 step=3 title=\"Install Appwrite\" %}\n\nInstall the JavaScript Appwrite SDK.\n\n```sh\nnpm install appwrite\n```\n{% /section %}\n{% section #step-4 step=4 title=\"Import Appwrite\" %}\nFind your project's ID in the **Settings** page.\n\n{% only_dark %}\n![Project settings screen](/images/docs/quick-starts/dark/project-id.avif)\n{% /only_dark %}\n{% only_light %}\n![Project settings screen](/images/docs/quick-starts/project-id.avif)\n{% /only_light %}\n\nCreate a new file `src/lib/appwrite.js` and add the following code to it, replace `<PROJECT_ID>` with your project ID.\n\n```client-web\nimport { Client, Account} from 'appwrite';\n\nexport const client = new Client();\n\nclient\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1')\n    .setProject('<PROJECT_ID>'); // Replace with your project ID\n\nexport const account = new Account(client);\nexport { ID } from 'appwrite';\n```\n{% /section %}\n{% section #step-5 step=5 title=\"Create a login page\" %}\nAdd the following code to `src/App.vue`.\n\n```html\n<template>\n  <div>\n    <p>\n      {{ loggedInUser ? `Logged in as ${loggedInUser.name}` : 'Not logged in' }}\n    </p>\n\n    <form>\n      <input type=\"email\" placeholder=\"Email\" v-model=\"email\" />\n      <input type=\"password\" placeholder=\"Password\" v-model=\"password\" />\n      <input type=\"text\" placeholder=\"Name\" v-model=\"name\" />\n      <button type=\"button\" @click=\"login(email, password)\">Login</button>\n      <button type=\"button\" @click=\"register\">\n        Register\n      </button>\n      <button type=\"button\" @click=\"logout\">\n        Logout\n      </button>\n    </form>\n  </div>\n</template>\n\n<script setup>\nimport { ref } from 'vue';\nimport { account, ID } from './lib/appwrite.js';\n\nconst loggedInUser = ref(null);\nconst email = ref('');\nconst password = ref('');\nconst name = ref('');\n\nconst login = async (email, password) => {\n  await account.createEmailPasswordSession({\n    email,\n    password\n  });\n  loggedInUser.value = await account.get();\n};\n\nconst register = async () => {\n  await account.create({\n    userId: ID.unique(),\n    email: email.value,\n    password: password.value,\n    name: name.value\n  });\n  login(email.value, password.value);\n};\n\nconst logout = async () => {\n  await account.deleteSession({\n    sessionId: 'current'\n  });\n  loggedInUser.value = null;\n};\n<\/script>\n```\n{% /section %}\n\n{% section #step-6 step=6 title=\"All set\" %}\nRun your project with `npm run dev -- --open --port 3000` and open [Localhost on Port 3000](http://localhost:3000) in your browser.\n{% /section %}\n";
export { vue_default as default };
